SPECIFICATION:

I would like you to implement a module named TopModule with the following
interface. All input and output ports are one bit unless otherwise
specified.

 - input  clk
 - input  reset
 - input  in
 - output out

Implement the following Moore state machine with two states, one input,
and one output. The reset state is B and reset is active-high
synchronous.

  B (out=1) --in=0--> A
  B (out=1) --in=1--> B
  A (out=0) --in=0--> B
  A (out=0) --in=1--> A



CANDIDATE RTL TO ATTACK:
```verilog
module TopModule (
    input  wire clk,
    input  wire reset,
    input  wire in,
    output wire out
);

    // State encoding: State A = 1'b0, State B = 1'b1
    // Reset state is B, so default/reset value is 1'b1.
    reg current_state, next_state;

    // State register with active-high synchronous reset
    always @(posedge clk) begin
        if (reset) begin
            current_state <= 1'b1; // State B
        end else begin
            current_state <= next_state;
        end
    end

    // Next-state logic based on Moore FSM specification:
    // B (1) --in=0--> A (0)
    // B (1) --in=1--> B (1)
    // A (0) --in=0--> B (1)
    // A (0) --in=1--> A (0)
    always @(*) begin
        case (current_state)
            1'b1: begin // State B
                if (in == 1'b0)
                    next_state = 1'b0; // to A
                else
                    next_state = 1'b1; // to B
            end
            1'b0: begin // State A
                if (in == 1'b0)
                    next_state = 1'b1; // to B
                else
                    next_state = 1'b0; // to A
            end
            default: next_state = 1'b1; // Default to B
        endcase
    end

    // Output logic (Moore machine: output depends only on the current state)
    // State B: out = 1
    // State A: out = 0
    assign out = current_state;

endmodule
```

